CREATE TABLE receipts(id VARCHAR2(36) PRIMARY KEY,trip_id VARCHAR2(36) NOT NULL,owner_id VARCHAR2(36) NOT NULL,object_key VARCHAR2(100) NOT NULL,mime_type VARCHAR2(100) NOT NULL,status VARCHAR2(20) NOT NULL CHECK(status IN ('UPLOADED','EXTRACTED','CONFIRMED')),extraction CLOB,created_at TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,version NUMBER(19) DEFAULT 0 NOT NULL);
CREATE INDEX receipts_trip ON receipts(trip_id);
ALTER TABLE expenses ADD(receipt_id VARCHAR2(36) REFERENCES receipts(id));
